import { RequestMethods } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { createApi } from '@reduxjs/toolkit/query/react';
export const signalApi = createApi({
    reducerPath: 'signalApi',
    tagTypes: ['signalTrendData', 'signalHistoryData'],
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        getSignalTrendData: builder.query({
            query: (signal_uuid) => ({
                url: `/signals/${signal_uuid}/trend`,
                method: RequestMethods.GET,
            }),
            providesTags: ['signalTrendData'],
        }),
        getSignalHistoryData: builder.query({
            query: (signal_uuid) => ({
                url: `/signals/${signal_uuid}/history`,
                method: RequestMethods.GET,
            }),
            providesTags: ['signalHistoryData'],
        }),
        createTradeServer: builder.mutation({
            query: (body) => ({
                url: '/trades/server',
                method: RequestMethods.POST,
                body,
            }),
        }),
        createTradeClient: builder.mutation({
            query: (body) => ({
                url: '/trades/client',
                method: RequestMethods.POST,
                body,
            }),
        }),
    }),
});
export const { useGetSignalTrendDataQuery, useGetSignalHistoryDataQuery, useCreateTradeServerMutation, useCreateTradeClientMutation, } = signalApi;
