import { useGetBitcoinPublicInformation, } from '05_entities/bitcoinPublicInformation';
import { useGetSignalList } from '05_entities/signal';
import { useCallback, useEffect } from 'react';
const useTitleHandler = () => {
    const information = useGetBitcoinPublicInformation();
    const signal_list = useGetSignalList();
    const titleHandler = useCallback(() => {
        if (!information) {
            document.title = 'MAIA';
            return;
        }
        if (!signal_list) {
            document.title = `${information.current_price.toFixed()}${information.trend_moment === 1 ? '\u2197' : '\u2198'} | MAIA`;
            return;
        }
        if (signal_list.length === 0) {
            document.title = `${information.current_price.toFixed()}${information.trend_moment === 1 ? '\u2197' : '\u2198'} | MAIA`;
            return;
        }
        document.title = `${information.current_price.toFixed()}${information.trend_moment === 1 ? '\u2197' : '\u2198'} | ${signal_list.length} | MAIA`;
    }, [information, signal_list]);
    useEffect(() => {
        titleHandler();
    }, [titleHandler]);
};
export { useTitleHandler };
