import { createSelector } from '@reduxjs/toolkit';
import { useAppSelector } from '06_shared/hooks/useAppSelector';
const EMPTY_LIST = [];
// Той самий патерн, що й у useGetTradeList: селектор типізовано
// локальною схемою, щоб не перетинати межу entities → app.
const selectSignalList = createSelector((signal) => signal?.signal_list, (signal_list) => signal_list ? Object.values(signal_list) : EMPTY_LIST);
const useGetSignalList = () => {
    const signal = useAppSelector((state) => state.signal);
    return selectSignalList(signal);
};
export { useGetSignalList };
